  "code": 200,
  "success": true,
  "message": "success",
  "data": {
    "id": "atcPtxnvqti5M",
    "name": "6.gif",
    "size": 33914,
    "mimeType": "image/gif",
    "token": "space/2020/09/22/01ee7202922d48688f61e34f12da5abc",
