	{
		"question": "What is Space in APITable?",
		"answers": [
			"Space is a collaboration platform for all members of your organization or team. Access your personalized managed and invited spaces by clicking on the space icon located in the upper left corner of the APITable workbench."
		]
	},
	{
		"question": "How can I check my current space plan and usage?",
		"answers": [
			"You can check your current Space plan and usage by navigating to the Space settings > Overview section."
		],
		"list": []
	},
	{
		"question": "How does APITable's pricing work?",
		"answers": [
			"APITable charges are based on a combination of fixed rates and seat rates. On APITable's Free plan, you get 5 seats for free. If you choose to subscribe, you'll be charged based on the subscription plan and the number of seats. ",
			"The Plus plan includes 5 available seats, and if you need to add more seats later, you'll need to pay a rate of 5 dollars/month/seat (annually).",
			"The Pro plan includes 5 available seats, and if you need to add more seats later, you'll need to pay a rate of 12 dollars/month/seat (annually).",
			"Here, 'seats' refers to the number of members joined in the space and doesn't include non-space members who are allowed to submit forms."
		]
	},
	{
		"question": "How do I upgrade my Space plan? ",
		"answers": [
			"With just a few clicks, you can upgrade your existing paid Space plan by navigating to Space settings > Upgrade and selecting a paid plan."
		]
	},
	{
		"question": "How does adding and removing members work on billing?",
		"answers": [
			"When you add members, you'll be charged a portion of the fee based on the time each member was added and the current billing cycle.",
			"When you remove members, you'll receive a credit for a portion of the fee based on the same calculation. These charges or credits will appear on your next billing statement."
		]
	},
	{
		"question": "How do I downgrade or unsubscribe?",
		"answers": [
			"If you want to downgrade your current plan, you can do it directly in the Space settings. For unsubscribing, we will assist you with downgrading or unsubscribing your subscription. Click the purple icon in the bottom right corner and send us a message or contact us at support@aitable.ai."
		]
	}
